public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		long K = in.nextLong();
		long sum = 0;
		for(int i=1; i<=K; i++) {
			for(int j=1; j<=K; j++) {
				for(int k=1; k<=K; k++) {
					sum = sum + gcd(k, gcd(i,j));
				}
			}
		}

		System.out.println(sum);

	}

	public static int gcd(int x, int y) {
		if(y == 0) {
			return x;
		}
		return gcd(y, x%y);
	}

}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int k = scan.nextInt();
		long sum = 0;
		for (int a = 1; a <= k; a++) {
			for (int b = 1; b <= k; b++) {
				int r = gcd(a, b);
				for (int c = 1; c <= k; c++) {
					sum += gcd(r, c);
				}
			}
		}
		System.out.println(sum);
	}

	public static int gcd(int a, int b) {
		if (a < b) {
			int tmp = a;
			a = b;
			b = tmp;
		}
		if (a % b == 0) {
			return b;
		} else {
			return gcd(b, a % b);
		}
	}
}

