import java.util.*;
public class Main {
    public static void main(String[] args) throws NumberFormatException {
        Scanner sc = new Scanner(System.in);

        String S = sc.nextLine().trim();
        String[] segments = S.split(" ");
        int N = Integer.parseInt(segments[0]);
        int K = Integer.parseInt(segments[1]);

        double result = 0;
        double np = (double)1.0 / N;
        for (int i = 1; i <= N; i++) {
            result += np * calcP(i, K);
        }
        System.out.println(result);
    }

    private static double calcP(int n, int k) {
        int score = n;
        int cnt = 0;
        while (score < k) {
            cnt++;
            score *= 2;
        }

        if (cnt > 0) {
            return Math.pow((double)0.5, cnt);
        } else {
            return 1;
        }
    }
}

import java.util.Scanner;

public class Main {

	public static void main(String args[]) {

		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int K = sc.nextInt();

		double p = 0;

		if(N < K) {

			for(int i=1;i<=N;i++) {
				if(K%i == 0 && ispow2(K/i)) {
					p += Math.pow(2, -1*((int)(log2(K/i))));
				}else {
					p += Math.pow(2, -1*((int)(log2(K/i) + 1)));
				}
			}

			p /= N;
		}else {
			for(int i=1;i<K;i++) {
				if(K%i == 0 && ispow2(K/i)) {
					p += Math.pow(2, -1*((int)(log2(K/i))));
				}else {
					p += Math.pow(2, -1*((int)(log2(K/i) + 1)));
				}
			}
			p /= N;

			p += (double)(N-K+1)/(double)N;
		}
		System.out.println(p);
	}

	public static boolean ispow2(int a) {
		int x = a & (a-1);
		if(x == 0) {
			return true;
		}else {
			return false;
		}
	}

	public static double log2(double a) {
		return Math.log(a)/Math.log(2);
	}
}

