		int ans = 0;
		for (int i = 0; i < n; i++) {
			int tmp = c;
			for (int j = 0; j < m; j++) {
				tmp += a[i][j] * b[j];
			}

			// System.err.printf("A%s SUM%s\n", i,tmp);
			if (tmp > 0) {
				ans++;
			}
		}
		return ans;
	}
