public class Main {

    public static void solve(InputReader in, PrintWriter out) throws Exception {

        int n = in.nextInt();
        int k = in.nextInt();


        int[] arr = new int[n+1];

        for(int i=1;i<=n;i++)
            arr[i]=in.nextInt();

        int[] dp = new int[n+1];

        dp[0]=0;
        dp[1]=0;
        dp[2]= Math.abs(arr[2]-arr[1]);


        for(int i=3;i<=n;i++)
        {
            int j=i;
            int c=1;
            dp[i]=Integer.MAX_VALUE;
            while(j-c>=1 && c<=k)
            {
                dp[i]= Math.min(dp[i],Math.abs(arr[i]-arr[j-c])+dp[j-c]);
                c++;
            }

        }
        out.println(dp[n]);

    }

